--
-- Table structure for table `paiements`
--

DROP TABLE IF EXISTS `paiements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `paiements` (
  `paiement_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `typeClient` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'valeur:Particulier,Societe',
  `modeExp` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'valeur:usage Personnel,Transport',
  `fullName` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nom de la societe ou de la personne.',
  `tel` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Numero de telephone',
  `nif` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chassis` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Numero de Chassis',
  `nouveauNum` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modeImma` tinyint NOT NULL COMMENT 'Mode d''immatriculation',
  `categorie_id` int unsigned DEFAULT '0',
  `typeCg` int unsigned DEFAULT '0' COMMENT 'type de Carte grise',
  `typeVignette` int unsigned DEFAULT '0' COMMENT 'type de Vignette',
  `autorisation_id` int unsigned DEFAULT '0' COMMENT 'Autorisation de Transport',
  `pv` bigint unsigned DEFAULT '0' COMMENT 'Poids Total Autorisé à Charge',
  `cu` bigint unsigned DEFAULT '0' COMMENT 'Charge Utile',
  `pf` int DEFAULT '0',
  `ptra` int DEFAULT '0',
  `nbrePlace` tinyint DEFAULT '0',
  `user_id` int NOT NULL,
  `validedBy` int DEFAULT '0',
  `agence_id` int DEFAULT NULL,
  `quartier_id` int DEFAULT NULL,
  `printed` tinyint DEFAULT '0' COMMENT '0=pas imprime 1=imprime',
  `qrcode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reference` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `oldereference` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type_document` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tous',
  `date_exp` datetime DEFAULT NULL,
  `status` tinyint DEFAULT '0' COMMENT 'o=non validé,1=validé,2=réjété,3=Resoumission;4=resoumis',
  `isautoriser` tinyint DEFAULT '0' COMMENT '0=non autoriser,1=autoriser',
  `terminale` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT 'PC',
  `type_paiement` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'nouveau' COMMENT 'Nouveau,renouvellement,mutation',
  `type_plaque` varchar(25) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `penalite` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`paiement_id`),
  UNIQUE KEY `reference_UNIQUE` (`reference`),
  KEY `paiements_categorie_id_foreign` (`categorie_id`),
  KEY `paiements_typeCartgrise_foreign_key_idx` (`typeCg`),
  KEY `paiements_typevignette_foreign_key_idx` (`typeVignette`),
  KEY `paiements_autorisation_foreign_key_idx` (`autorisation_id`),
  KEY `paiements_users_foreign_key_idx` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=494 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `paiements`
--

LOCK TABLES `paiements` WRITE;
